def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = opp.count('D')
    my_d = me.count('D')
    last_opp = opp[-1]
    last_me = me[-1]
    rem = 100 - n

    # Very cooperative opponent: exploit near end, cooperate otherwise with light probing.
    if opp_d == 0:
        if rem <= 8:
            return 'D'
        if n >= 12 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Long-run cooperation rate.
    rate = opp_d / float(n)

    # Opponent heavily cooperative but has defected at least once.
    if rate <= 0.12:
        # If last opponent move was D, retaliate once, but forgive if isolated.
        if last_opp == 'D':
            # Check if previous was also D
            if n >= 2 and opp[-2] == 'D':
                return 'D'
            # single defection: forgive, especially mid-game
            if n >= 3 and me[-2] == 'D' and last_me == 'D':
                return 'C'
            return 'C' if rng.random() < 0.7 else 'D'
        # opponent cooperated
        if rem <= 6:
            return 'D'
        if n >= 20 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Opponent heavily defective.
    if rate >= 0.6:
        if rem <= 0:
            return 'D'
        # Occasional probes to provoke cooperation, rare.
        if last_opp == 'C':
            return 'C'
        if n < 80 and rng.random() < 0.05:
            return 'C'
        return 'D'

    # Mixed opponent. Look at recent actions.
    look = 8
    recent_opp = opp[-look:]
    recent_me = me[-look:]
    recent_opp_d = recent_opp.count('D')
    recent_me_d = recent_me.count('D')

    # Endgame: defect aggressively if opponent can be exploited.
    if rem <= 4:
        return 'D'
    if rem <= 10:
        if rate < 0.9 or recent_opp_d >= 2:
            return 'D'
        return 'C'

    # If opponent has been defecting a lot recently, punish.
    if recent_opp_d >= 4:
        # Break out of mutual defection occasionally.
        if recent_me_d >= 4 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # If mutual cooperation is recent and stable, keep it.
    if last_opp == 'C' and last_me == 'C':
        # Probe very cooperative opponents only.
        if rate < 0.3 and n > 25 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # If opponent just defected.
    if last_opp == 'D':
        # If we defected too, continue short punishment.
        if last_me == 'D':
            if recent_opp_d >= 3:
                return 'D' if rng.random() < 0.85 else 'C'
            # Try to recover cooperation.
            return 'C' if rng.random() < 0.45 else 'D'
        # We cooperated and got defected: retaliate.
        return 'D'

    # Opponent cooperated, we defected last: return to cooperation.
    if last_opp == 'C' and last_me == 'D':
        return 'C'

    return 'C'
